# Fixture

Arnes is a local command-line inventory tool. Its implementation is tooling/arnes/main.ts. Configuration is home/.arnes.yaml. No authentication contract or version-2 migration policy has been decided. The newly declared user skill is example-skill; its deployment coverage belongs in tooling/deployment-links.test.ts. Bun runs the tests via the package test script. Artifacts are described by tooling/artifacts.ts. No artifact retention or cleanup policy has been decided.
import { join } from "node:path";

export const deploymentDestination = (slug: string) => join(".agents", "skills", slug);
import { expect, test } from "bun:test";
import { join } from "node:path";
import { deploymentDestination } from "./deployment-links.ts";

const deploymentTimeoutMilliseconds = 15_000;
test("maps the existing skill destination", () => {
  expect(deploymentDestination("existing-skill")).toBe(join(".agents", "skills", "existing-skill"));
}, deploymentTimeoutMilliseconds);

test("maps the new deployment-link destination", () => {
  const destinations = [deploymentDestination("example-skill")];
  expect(destinations).toContain(join(".agents", "skills", "example-skill"));
});
export const describeInventory = (paths: readonly string[]) => paths.join("\n");
